arguments.command:
for b in rachel monica phoebe joey chandler ross; do
  echo "=== $b ===";
  git log --reverse --format='%H %ci' origin/friend/$b | while read sha ts; do
    msg=$(git show $sha --format=%B -s 2>/dev/null | tr '\n' ' ' | grep -o 'Episode: [A-Z0-9/]*');
    echo "$sha $ts $msg";
  done | grep S06/E06;
done
